import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%80%90%E6%9B%B8%E7%B1%8D%E3%80%91IntroductionToAlgorithms.html","title":"【書籍】IntroductionToAlgorithms","lang":"en-US","frontmatter":{},"git":{"createdTime":1664611463000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":4}]},"readingTime":{"minutes":0.71,"words":213},"filePathRelative":"【書籍】IntroductionToAlgorithms.md"}`),a={name:`【書籍】IntroductionToAlgorithms.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="【書籍】introductiontoalgorithms" tabindex="-1"><a class="header-anchor" href="#【書籍】introductiontoalgorithms"><span>【書籍】IntroductionToAlgorithms</span></a></h1><p><a href="./アルゴリズム本.html">アルゴリズム本</a>、<a href="./書籍.html">書籍</a>、<a href="./アルゴリズム.html">アルゴリズム</a></p><p><a href="https://www.amazon.co.jp/dp/B094WZNKP2?&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=92c689364fbdb9495d57937c99df064c&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: Introduction to Algorithms, fourth edition (English Edition)</a></p><p>割と定番のアルゴリズムの本。 手元に置いておいて何度も参照する。この本に無いものはその分野の本を当たれば良い、という感じの、各分野に進むための基本となる事が全部揃っていて、解説は分かりやすく、良く書けていると思う。 アルゴリズムの本を一冊選べと言われたらこれだろう。</p><p>Introductionと言うが、専門分野でない範囲で必要な事は全部入っている。専門分野に進む前のIntroductionという感じで、これ持っておけば十分、というくらいに詳しく網羅的な本だ。</p><p>自分が買ったのは3rd editionだがリンクは最新の4th editionにしておく。</p><p>Knuthの<a href="./【書籍】TheArtOfComputerProgramming.html">【書籍】TheArtOfComputerProgramming</a>はより詳しいが、記述が古く現代で読むには無駄に面倒だな、という印象。Introduction to Algorithmsの方が説明が現代向きなので、まずこちらを読んでから必要があればKnuthの本に進むのが良いと思うし、だいたいこの本で十分目的に足りる。</p><h2 id="heapソート" tabindex="-1"><a class="header-anchor" href="#heapソート"><span>Heapソート</span></a></h2><p><a href="./Heap.html">Heap</a></p><h2 id="文字列マッチを読む-2026-07-16-木" tabindex="-1"><a class="header-anchor" href="#文字列マッチを読む-2026-07-16-木"><span>文字列マッチを読む 2026-07-16 (木)</span></a></h2><p>32.3から読んでいく。＞<a href="./文字列マッチ.html">文字列マッチ</a></p><h2 id="dynamic-programing-2026-07-03-金" tabindex="-1"><a class="header-anchor" href="#dynamic-programing-2026-07-03-金"><span>Dynamic Programing 2026-07-03 (金)</span></a></h2><p>Dynamic Programmingのあたりを読む。＞ついでに<a href="./サイコロ本.html">サイコロ本</a>の<a href="./HMM.html">HMM</a>を追う</p><p><a href="./Diff.html">Diff</a>もDPのLCS Diffのサブセクションの内容がベース。</p><h2 id="_2022-10-02" tabindex="-1"><a class="header-anchor" href="#_2022-10-02"><span>2022-10-02</span></a></h2><p>2章のinsertion sortのあたりを読む。擬似コードはJavaっぽい普通の言語なので<a href="./【書籍】TheArtOfComputerProgramming.html">【書籍】TheArtOfComputerProgramming</a>よりは遥かに読みやすいね。普通に本作ったらこうなるよな。 疑似コードとかbig-Oノーテーションとかの以後のアルゴリズムの説明に必要そうな話をざっと読む。</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};